service.method:

		INSERT INTO SUDGL
				(HOUSE_CODE
		       , COMPANY_CODE
		       , USE_NUMBER
               , ADD_DATE   
               , ADD_TIME   
               , ADD_USER_ID       
		       , CHANGE_DATE    
               , CHANGE_TIME    
               , CHANGE_USER_ID
               , DEL_FLAG 
               , SUBJECT
               , CONTENT
		       , SORT_SEQ
		       , CORP_FLAG
		       , USE_FLAG
		       , EXTERNAL_FLAG
		       , FORM_ID  
		       , YD_NUMBER              
		)VALUES(
     	         ${session.HOUSE_CODE}
     	       , ${session.COMPANY_CODE}
		       , ${USE_NUMBER}             
	           , ${current.date}    
               , ${current.time}
               , ${session.ID}
               , ${current.date}    
               , ${current.time}    
               , ${session.ID}   
               , 'N'
		       , ${SUBJECT}           
     		   , ${CONTENT}
     		   , ${SORT_SEQ}
     		   , CASE ${CORP_FLAG} WHEN '1' THEN 'Y' ELSE 'N' END
     		   , CASE ${USE_FLAG} WHEN '1' THEN 'Y' ELSE 'N' END
     		   , CASE ${EXTERNAL_FLAG} WHEN '1' THEN 'Y' ELSE 'N' END
     		   , ${FORM_ID}
     		   , ${YD_NUMBER}
		)


		UPDATE SUDGL
      	   SET CHANGE_DATE 	     = ${current.DATE}
			 , CHANGE_TIME       = ${current.TIME}
			 , CHANGE_USER_ID    = ${session.ID}
			 , SUBJECT           = ${SUBJECT}
			 , CONTENT           = ${CONTENT}
			 , SORT_SEQ          = ${SORT_SEQ}
			 , USE_NUMBER		 = ${USE_NUMBER}
			 , CORP_FLAG         = CASE ${CORP_FLAG} WHEN '1' THEN 'Y' ELSE 'N' END
			 , USE_FLAG          = CASE ${USE_FLAG} WHEN '1' THEN 'Y' ELSE 'N' END
			 , EXTERNAL_FLAG     = CASE ${EXTERNAL_FLAG} WHEN '1' THEN 'Y' ELSE 'N' END
			 , FORM_ID           = ${FORM_ID}			 
	     WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
		   AND COMPANY_CODE      = ${session.COMPANY_CODE}
		   AND YD_NUMBER         = ${YD_NUMBER}	   
		   AND #DB_OWNER#NVL(DEL_FLAG,'N') = 'N'


	DELETE FROM SUDGL
     WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
	   AND COMPANY_CODE      = ${session.COMPANY_CODE}
	   AND YD_NUMBER         = ${YD_NUMBER}


DELETE
  FROM SAPUD
 WHERE 
	 	HOUSE_CODE 		= ${session.HOUSE_CODE}  
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}
	AND KEY_NUMBER		= ${KEY_NUMBER}
